questionvariables.text:
/* Possible [|cos|, |sin|] pairs from Pythagorean triples */
cos_values : [
    [3/5, 4/5],
    [4/5, 3/5],
    [5/13, 12/13],
    [12/13, 5/13]
];

/* Select a random cosine/sine pair */
variant : rand(cos_values);

cos_abs : variant[1];
sin_abs : variant[2];

/* Randomly select a quadrant: II, III or IV (all angles greater than 90 degrees; IV added) */
quadrant : rand([2,3,4]);
quadnames : ["I", "II", "III", "IV"];
quadname : quadnames[quadrant];

/* Determine the signs: cos is negative in II and III; sin is positive only in II.
   (Rewritten without assignments inside an if-block.) */
cos_value : if quadrant = 4 then cos_abs else -cos_abs;
sin_value : if quadrant = 2 then sin_abs else -sin_abs;

/* Correct answer */
ta : sin_value;

/* Student mistake 1: correct magnitude but wrong sign */
ta_mistake1 : -sin_value;

/* Student mistake 2: uses the cosine magnitude as the sine value (either sign) */
ta_mistake2 : cos_abs;

/* Student mistake 3: forgot to take the square root, i.e. gave sin^2 (either sign) */
ta_mistake3 : sin_abs^2;
